      const img = L.images["" + state] || L.images.normal;
      if (T.img) { if (img) { T.img.style.display = "block"; if (T.img.getAttribute("src") !== img) T.img.setAttribute("src", img); } else T.img.style.display = "none"; }
      const lab = (L.labels[state] || L.label || "");
