        const tx = hmk("div", { width: "100%", whiteSpace: "pre-wrap", textAlign: L.align, color: L.color, fontFamily: '"' + L.fontFamily + '", Georgia, serif', lineHeight: "1.15", pointerEvents: "none", textShadow: L.shadow ? "0 2px 12px rgba(0,0,0,.7)" : "none" });
        if (L.strokeWidth > 0) { tx.style.webkitTextStroke = L.strokeWidth + "px " + L.strokeColor; tx.style.paintOrder = "stroke fill"; }
        tx.textContent = L.text;
